create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,name text,role text not null default 'customer',created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,cost numeric(12,2) not null,auto_margin numeric(12,2) not null,selling_price numeric(12,2) not null,category text default 'Uncategorized',active boolean default true,created_at timestamptz default now());
create table if not exists customers(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),name text not null,mobile text,email text,created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_id uuid references customers(id),status text not null,payment_method text,payment_status text,subtotal numeric(12,2) default 0,shipping numeric(12,2) default 0,total numeric(12,2) default 0,created_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,product_id uuid references products(id),quantity int not null,unit_price numeric(12,2) not null);
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id),provider text,provider_reference text,amount numeric(12,2),status text,created_at timestamptz default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),entity_type text,entity_id uuid,action text,actor text,metadata jsonb,created_at timestamptz default now());
